import { GoogleGenAI } from '@google/genai';
import { createClient } from '@supabase/supabase-js';
import React, { useState, useEffect, useRef, useCallback } from 'react';
import ReactDOM from 'react-dom/client';
import { ChatMessage, UserProfile } from './types';
import { generateId } from './utils';

// Configuration
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Assuming these are injected via environment or placeholders
// In a real environment, you'd use process.env.SUPABASE_URL and process.env.SUPABASE_ANON_KEY
const supabaseUrl = (process.env as any).SUPABASE_URL || 'https://your-project.supabase.co';
const supabaseKey = (process.env as any).SUPABASE_ANON_KEY || 'your-anon-key';
const supabase = createClient(supabaseUrl, supabaseKey);

function App() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isBooting, setIsBooting] = useState(true);
  const [isJoining, setIsJoining] = useState(false);
  const [loginFields, setLoginFields] = useState({ name: '', title: 'WANDERER' });
  const [isTyping, setIsTyping] = useState(false);
  const [networkStatus, setNetworkStatus] = useState<'OFFLINE' | 'CONNECTED'>('OFFLINE');

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const channelRef = useRef<any>(null);

  // Boot sequence
  useEffect(() => {
    const timer = setTimeout(() => setIsBooting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  // Auto scroll
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const addMessage = useCallback((msg: ChatMessage) => {
    setMessages(prev => {
      // Prevent duplicates from broadcast if they already exist locally
      if (prev.find(m => m.id === msg.id)) return prev;
      return [...prev, msg];
    });
  }, []);

  // Initialize Supabase Realtime
  useEffect(() => {
    if (!user) return;

    const channel = supabase.channel('void-room', {
      config: {
        broadcast: { self: false },
      },
    });

    channel
      .on('broadcast', { event: 'chat_message' }, ({ payload }) => {
        addMessage(payload);
      })
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          setNetworkStatus('CONNECTED');
        }
      });

    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, addMessage]);

  // Simulate "Strangers" (Gemini Bots)
  const simulateStrangers = useCallback(async (context?: string) => {
    setIsTyping(true);
    try {
      const prompt = `
        You are simulating a futuristic retro-gaming terminal chatroom called "VOID_CHAT".
        The current user is ${user?.name} (${user?.title}).
        Recent history: ${messages.slice(-5).map(m => `${m.sender.name}: ${m.text}`).join(' | ')}
        ${context ? `Triggered by: "${context}"` : "Random chatter."}

        TASK: Generate 1 short message from a "Ghost in the Machine" or "Cyber Phantom".
        Names: "Null_Ptr", "Xero_Day", "Root_Shell", "Neon_Spectre".
        Title: "AI_NODE_EX", "GHOST_DATA", "KERNEL_LOG".

        Return ONLY a JSON object: {"name": "...", "title": "...", "text": "..."}
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
      });

      const text = response.text || '{}';
      const match = text.match(/\{.*\}/s);
      if (match) {
        const bot = JSON.parse(match[0]);
        const botMsg = {
          id: generateId(),
          sender: { name: bot.name, title: bot.title },
          text: bot.text,
          timestamp: Date.now(),
          isSystem: false
        };
        addMessage(botMsg);
        // Broadcast the bot message so other real people see the same bot
        channelRef.current?.send({
          type: 'broadcast',
          event: 'chat_message',
          payload: botMsg,
        });
      }
    } catch (e) {
      console.error("AI node failed", e);
    } finally {
      setIsTyping(false);
    }
  }, [user, messages, addMessage]);

  // Occasionally trigger bot chatter
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => {
      if (Math.random() > 0.8 && !isTyping) {
        simulateStrangers();
      }
    }, 30000);
    return () => clearInterval(interval);
  }, [user, isTyping, simulateStrangers]);

  const handleJoin = (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginFields.name.trim()) return;
    setIsJoining(true);

    setTimeout(() => {
      const newUser = { name: loginFields.name.toUpperCase(), title: loginFields.title.toUpperCase() };
      setUser(newUser);
      setIsJoining(false);

      const welcomeMsg: ChatMessage = {
        id: generateId(),
        sender: { name: 'SYSTEM', title: 'KERNEL' },
        text: `UPLINK ESTABLISHED. WELCOME, ${newUser.name}.`,
        timestamp: Date.now(),
        isSystem: true
      };
      addMessage(welcomeMsg);
    }, 1200);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || !user) return;

    const userMsg: ChatMessage = {
      id: generateId(),
      sender: user,
      text: inputValue,
      timestamp: Date.now(),
      isSystem: false
    };

    // Add locally
    addMessage(userMsg);

    // Broadcast to real users
    channelRef.current?.send({
      type: 'broadcast',
      event: 'chat_message',
      payload: userMsg,
    });

    setInputValue('');

    // Low chance to trigger a bot reply
    if (Math.random() > 0.6) {
      setTimeout(() => simulateStrangers(inputValue), 2000);
    }
  };

  if (isBooting) {
    return (
      <div className="terminal-container boot-screen">
        <div className="scanlines"></div>
        <div className="boot-text">
          <p>LOAD "OS_VIRTUAL_VOID",8,1</p>
          <p>SEARCHING FOR PEERS...</p>
          <p>SYNCING REALTIME NODES...</p>
          <p>READY.</p>
          <span className="cursor">_</span>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="terminal-container login-screen">
        <div className="scanlines"></div>
        <div className="crt-glow"></div>
        <form className="login-form" onSubmit={handleJoin}>
          <div className="ascii-art">
            <pre>{`
  _   _ _____ ___  _   _ 
 | \\ | | ____/ _ \\| \\ | |
 |  \\| |  _|| | | |  \\| |
 | |\\  | |__| |_| | |\\  |
 |_| \\_|_____\\___/|_| \\_|
     C H A T R O O M
            `}</pre>
          </div>
          <div className="input-group">
            <label>ENTER IDENTITY:</label>
            <input 
              autoFocus
              maxLength={15}
              placeholder="HANDLE..."
              value={loginFields.name}
              onChange={e => setLoginFields({...loginFields, name: e.target.value})}
              disabled={isJoining}
            />
          </div>
          <div className="input-group">
            <label>ASSIGN RANK:</label>
            <input 
              maxLength={20}
              placeholder="e.g. INFILTRATOR"
              value={loginFields.title}
              onChange={e => setLoginFields({...loginFields, title: e.target.value})}
              disabled={isJoining}
            />
          </div>
          <button type="submit" disabled={isJoining || !loginFields.name}>
            {isJoining ? 'ESTABLISHING HANDSHAKE...' : 'CONNECT TO VOID'}
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="terminal-container main-chat">
      <div className="scanlines"></div>
      <div className="crt-glow"></div>

      <header className="terminal-header">
        <div className="status-bit">USER: {user.name}</div>
