      </header>

      <div className="message-area" ref={scrollRef}>
        {messages.map((msg) => (
          <div key={msg.id} className={`message-item ${msg.isSystem ? 'system' : ''} ${msg.sender.name === user.name ? 'self' : ''}`}>
            <div className="msg-meta">
              <span className="msg-name">[{msg.sender.name}]</span>
              <span className="msg-title">({msg.sender.title})</span>
            </div>
