          placeholder="TYPE MESSAGE..."
          autoComplete="off"
        />
      </form>

      <footer className="terminal-footer">
        REALTIME BROADCAST ACTIVE | NODE: {supabaseUrl.split('.')[0].split('//')[1]} | EST. 1989
      </footer>
    </div>
  );
}

