:root {
  --bg-color: #050505;
  --terminal-green: #33ff33;
  --terminal-green-dim: #116611;
  --terminal-white: #e0e0e0;
  --crt-flicker: rgba(51, 255, 51, 0.02);
  --font-mono: 'Courier New', Courier, monospace;
}

* {
  box-sizing: border-box;
}

body, html {
  margin: 0;
  padding: 0;
  height: 100%;
  background-color: var(--bg-color);
  color: var(--terminal-green);
  font-family: var(--font-mono);
  overflow: hidden;
}

/* CRT EFFECTS */
.scanlines {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(
    rgba(18, 16, 16, 0) 50%,
    rgba(0, 0, 0, 0.25) 50%
  ),
  linear-gradient(
    90deg,
    rgba(255, 0, 0, 0.06),
    rgba(0, 255, 0, 0.02),
    rgba(0, 0, 255, 0.06)
  );
  background-size: 100% 4px, 3px 100%;
  z-index: 1000;
  pointer-events: none;
}

.crt-glow {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circleAtCenter, transparent, rgba(0,0,0,0.4));
  box-shadow: inset 0 0 100px rgba(51, 255, 51, 0.1);
  pointer-events: none;
  z-index: 999;
}

/* APP CONTAINER */
.terminal-container {
  height: 100vh;
  display: flex;
  flex-direction: column;
  padding: 20px;
  position: relative;
  text-shadow: 0 0 5px var(--terminal-green);
}

/* BOOT SCREEN */
.boot-screen {
  justify-content: center;
  align-items: flex-start;
  padding: 100px;
}

.boot-text p {
  margin: 5px 0;
  font-size: 1.2rem;
}

.cursor {
  animation: blink 0.8s infinite;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

/* LOGIN SCREEN */
.login-screen {
  justify-content: center;
  align-items: center;
}

.login-form {
  border: 2px solid var(--terminal-green);
  padding: 40px;
  background: rgba(0, 20, 0, 0.8);
  box-shadow: 0 0 20px var(--terminal-green-dim);
  max-width: 500px;
  width: 100%;
}

.ascii-art pre {
  color: var(--terminal-green);
  line-height: 1;
  margin-bottom: 30px;
  text-align: center;
}

.input-group {
  margin-bottom: 20px;
}

.input-group label {
  display: block;
  margin-bottom: 8px;
  font-size: 0.9rem;
}

.input-group input {
  width: 100%;
  background: transparent;
  border: 1px solid var(--terminal-green-dim);
  padding: 10px;
  color: var(--terminal-white);
  font-family: var(--font-mono);
  font-size: 1.1rem;
  outline: none;
}

.input-group input:focus {
  border-color: var(--terminal-green);
  box-shadow: 0 0 10px var(--terminal-green-dim);
}

button {
  width: 100%;
  background: var(--terminal-green);
  color: black;
  border: none;
  padding: 12px;
  font-family: var(--font-mono);
  font-weight: bold;
  cursor: pointer;
  font-size: 1rem;
  transition: all 0.2s;
}

button:hover:not(:disabled) {
  background: var(--terminal-white);
  transform: scale(1.02);
}

button:disabled {
  background: var(--terminal-green-dim);
  cursor: not-allowed;
}

/* MAIN CHAT AREA */
.main-chat {
  padding: 0;
}

.terminal-header {
  padding: 10px 20px;
  border-bottom: 2px solid var(--terminal-green-dim);
  display: flex;
  justify-content: space-between;
  font-size: 0.8rem;
  background: rgba(0, 10, 0, 0.5);
}

.status-bit.connected {
  color: var(--terminal-white);
  animation: flicker 0.1s infinite alternate;
}

.status-bit.offline {
  color: #ff3333;
}

@keyframes flicker {
  from { opacity: 0.8; }
  to { opacity: 1; }
}

.message-area {
  flex: 1;
  overflow-y: auto;
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 15px;
  scroll-behavior: smooth;
}

.message-item {
  max-width: 80%;
  animation: slideIn 0.3s ease-out;
}

@keyframes slideIn {
  from { transform: translateX(-10px); opacity: 0; }
  to { transform: translateX(0); opacity: 1; }
}

.message-item.self {
  align-self: flex-end;
  text-align: right;
  color: var(--terminal-white);
}

.msg-meta {
  font-size: 0.75rem;
  margin-bottom: 4px;
}

.msg-name {
  font-weight: bold;
  margin-right: 8px;
}

.msg-title {
  color: var(--terminal-green-dim);
}

.message-item.self .msg-title {
  color: #888;
}

.msg-text {
  font-size: 1rem;
  line-height: 1.4;
  word-wrap: break-word;
}

.message-item.system {
  width: 100%;
  max-width: 100%;
  text-align: center;
  color: var(--terminal-green-dim);
  border-top: 1px dashed var(--terminal-green-dim);
  border-bottom: 1px dashed var(--terminal-green-dim);
  padding: 5px 0;
  margin: 10px 0;
}

.message-item.typing .msg-text {
  animation: pulse 1.5s infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 0.4; }
  50% { opacity: 1; }
}

/* INPUT BAR */
.terminal-input-bar {
  display: flex;
  align-items: center;
  padding: 15px 20px;
  border-top: 2px solid var(--terminal-green-dim);
  background: rgba(0, 15, 0, 0.9);
}

.prompt {
  margin-right: 15px;
  font-size: 1.2rem;
  font-weight: bold;
}

.terminal-input-bar input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--terminal-green);
  font-family: var(--font-mono);
  font-size: 1.1rem;
}

.terminal-footer {
  font-size: 0.65rem;
  text-align: center;
  padding: 5px;
  color: var(--terminal-green-dim);
  background: #000;
}

/* SCROLLBAR */
.message-area::-webkit-scrollbar {
  width: 8px;
}
.message-area::-webkit-scrollbar-track {
  background: #000;
}
.message-area::-webkit-scrollbar-thumb {
  background: var(--terminal-green-dim);
}
.message-area::-webkit-scrollbar-thumb:hover {
  background: var(--terminal-green);
}

/* RESPONSIVE */
@media (max-width: 600px) {
  .login-form {
    padding: 20px;
    border: none;
  }
  .ascii-art pre {
    font-size: 0.6rem;
  }
  .message-item {
    max-width: 95%;
  }
}

