import { GoogleGenAI } from '@google/genai';
import { createClient } from '@supabase/supabase-js';
import React, { useState, useEffect, useRef, useCallback } from 'react';
import ReactDOM from 'react-dom/client';
import { ChatMessage, UserProfile } from './types';
import { generateId } from './utils';

// Configuration
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

// Using Supabase credentials from environment
const supabaseUrl = (process.env as any).SUPABASE_URL || 'https://your-project.supabase.co';
const supabaseKey = (process.env as any).SUPABASE_ANON_KEY || 'your-anon-key';
const supabase = createClient(supabaseUrl, supabaseKey);

function App() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isBooting, setIsBooting] = useState(true);
  const [isJoining, setIsJoining] = useState(false);
  const [loginFields, setLoginFields] = useState({ name: '', title: 'WANDERER' });
  const [isTyping, setIsTyping] = useState(false);
  const [networkStatus, setNetworkStatus] = useState<'OFFLINE' | 'CONNECTED'>('OFFLINE');

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Boot sequence
  useEffect(() => {
    const timer = setTimeout(() => setIsBooting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  // Auto scroll
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const mapDbToMessage = (payload: any): ChatMessage => ({
    id: payload.id,
    sender: { name: payload.handle, title: payload.rank },
    text: payload.content,
    timestamp: new Date(payload.created_at).getTime(),
    isSystem: payload.handle === 'SYSTEM'
  });

  // Initialize Supabase Realtime Table Subscription
  useEffect(() => {
    if (!user) return;

    // Subscribe to new rows in the 'messages' table
    const channel = supabase
      .channel('schema-db-changes')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'messages',
          filter: `room_id=eq.void-room`
        },
        (payload) => {
          const newMessage = mapDbToMessage(payload.new);
          setMessages(prev => {
            if (prev.find(m => m.id === newMessage.id)) return prev;
            return [...prev, newMessage];
          });
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          setNetworkStatus('CONNECTED');
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user]);

  // Simulate "Strangers" (Gemini Bots)
  const simulateStrangers = useCallback(async (context?: string) => {
    setIsTyping(true);
    try {
      const prompt = `
        You are simulating a futuristic retro-gaming terminal chatroom called "VOID_CHAT".
        The current user is ${user?.name} (${user?.title}).
        Recent history: ${messages.slice(-5).map(m => `${m.sender.name}: ${m.text}`).join(' | ')}
        ${context ? `Triggered by: "${context}"` : "Random chatter."}

        TASK: Generate 1 short message from a "Ghost in the Machine" or "Cyber Phantom".
        Names: "Null_Ptr", "Xero_Day", "Root_Shell", "Neon_Spectre", "Void_Walker".
        Title: "AI_NODE_EX", "GHOST_DATA", "KERNEL_LOG", "S0UL_V2".

        Return ONLY a JSON object: {"name": "...", "title": "...", "text": "..."}
      `;

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
      });

      const text = response.text || '{}';
      const match = text.match(/\{.*\}/s);
      if (match) {
        const bot = JSON.parse(match[0]);
        // Insert bot message into DB so everyone sees it
        await supabase.from('messages').insert({
          handle: bot.name,
          rank: bot.title,
          content: bot.text,
          room_id: 'void-room'
        });
      }
    } catch (e) {
      console.error("AI node synchronization failed", e);
    } finally {
      setIsTyping(false);
    }
  }, [user, messages]);

  // Occasionally trigger bot chatter
  useEffect(() => {
    if (!user) return;
    const interval = setInterval(() => {
      if (Math.random() > 0.8 && !isTyping) {
        simulateStrangers();
      }
    }, 45000);
    return () => clearInterval(interval);
  }, [user, isTyping, simulateStrangers]);

  const handleJoin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginFields.name.trim()) return;
    setIsJoining(true);

    // Fetch initial history from DB
    const { data, error } = await supabase
      .from('messages')
      .select('*')
      .eq('room_id', 'void-room')
      .order('created_at', { ascending: true })
      .limit(50);

    if (error) {
      console.error("Failed to fetch history", error);
    } else if (data) {
      setMessages(data.map(mapDbToMessage));
    }

    const newUser = { name: loginFields.name.toUpperCase(), title: loginFields.title.toUpperCase() };
    setUser(newUser);
    setIsJoining(false);

    // Add a local session system message (not necessarily saved to DB)
    const welcomeMsg: ChatMessage = {
      id: generateId(),
      sender: { name: 'SYSTEM', title: 'KERNEL' },
      text: `UPLINK ESTABLISHED. ARCHIVE LOADED. WELCOME, ${newUser.name}.`,
      timestamp: Date.now(),
      isSystem: true
    };
    setMessages(prev => [...prev, welcomeMsg]);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || !user) return;

    const textToSend = inputValue;
    setInputValue('');

    // Save to Supabase (Realtime listener handles updating the UI)
    const { error } = await supabase.from('messages').insert({
      handle: user.name,
      rank: user.title,
      content: textToSend,
      room_id: 'void-room'
    });

    if (error) {
      console.error("Transmission error", error);
      const errorMsg: ChatMessage = {
        id: generateId(),
        sender: { name: 'SYSTEM', title: 'ERROR' },
        text: `TRANSMISSION FAILED: ${error.message}`,
        timestamp: Date.now(),
        isSystem: true
      };
      setMessages(prev => [...prev, errorMsg]);
    }

    // Low chance to trigger a bot reply
    if (Math.random() > 0.7) {
      setTimeout(() => simulateStrangers(textToSend), 1500);
    }
  };

  if (isBooting) {
    return (
      <div className="terminal-container boot-screen">
        <div className="scanlines"></div>
        <div className="boot-text">
          <p>LOAD "OS_VIRTUAL_VOID",8,1</p>
          <p>SYNCING CLOUD_DB NODES...</p>
          <p>FETCHING ARCHIVES...</p>
          <p>READY.</p>
          <span className="cursor">_</span>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="terminal-container login-screen">
        <div className="scanlines"></div>
        <div className="crt-glow"></div>
        <form className="login-form" onSubmit={handleJoin}>
          <div className="ascii-art">
            <pre>{`
  _   _ _____ ___  _   _ 
 | \\ | | ____/ _ \\| \\ | |
 |  \\| |  _|| | | |  \\| |
 | |\\  | |__| |_| | |\\  |
 |_| \\_|_____\\___/|_| \\_|
     PERSISTENT_VOID
            `}</pre>
          </div>
          <div className="input-group">
            <label>ENTER IDENTITY:</label>
            <input 
              autoFocus
              maxLength={15}
              placeholder="HANDLE..."
              value={loginFields.name}
              onChange={e => setLoginFields({...loginFields, name: e.target.value})}
              disabled={isJoining}
            />
          </div>
          <div className="input-group">
            <label>ASSIGN RANK:</label>
            <input 
              maxLength={20}
              placeholder="e.g. INFILTRATOR"
              value={loginFields.title}
              onChange={e => setLoginFields({...loginFields, title: e.target.value})}
              disabled={isJoining}
            />
          </div>
          <button type="submit" disabled={isJoining || !loginFields.name}>
            {isJoining ? 'FETCHING ARCHIVES...' : 'CONNECT TO PERSISTENT VOID'}
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="terminal-container main-chat">
      <div className="scanlines"></div>
      <div className="crt-glow"></div>

      <header className="terminal-header">
        <div className="status-bit">USER: {user.name}</div>
        <div className="status-bit">RANK: {user.title}</div>
        <div className={`status-bit ${networkStatus.toLowerCase()}`}>
          DB_SYNC: {networkStatus}
        </div>
      </header>

      <div className="message-area" ref={scrollRef}>
        {messages.map((msg) => (
          <div key={msg.id} className={`message-item ${msg.isSystem ? 'system' : ''} ${msg.sender.name === user.name ? 'self' : ''}`}>
            <div className="msg-meta">
              <span className="msg-name">[{msg.sender.name}]</span>
              <span className="msg-title">({msg.sender.title})</span>
            </div>
            <div className="msg-text">{msg.text}</div>
          </div>
        ))}
        {isTyping && (
          <div className="message-item typing">
            <span className="msg-name">[GHOST]</span>
            <span className="msg-text italic">Interpreting signal...</span>
          </div>
        )}
      </div>

      <form className="terminal-input-bar" onSubmit={handleSendMessage}>
        <span className="prompt">></span>
        <input 
          ref={inputRef}
          autoFocus
          value={inputValue}
          onChange={e => setInputValue(e.target.value)}
          placeholder="TYPE MESSAGE..."
          autoComplete="off"
        />
      </form>

      <footer className="terminal-footer">
        SUPABASE_CDC_SYNC | CLUSTER: {supabaseUrl.split('.')[0].split('//')[1]} | EST. 1989
      </footer>
    </div>
  );
}

const rootElement = document.getElementById('root');
if (rootElement) {
  const root = ReactDOM.createRoot(rootElement);
  root.render(<App />);
}

