import { createClient } from '@supabase/supabase-js';
import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom/client';
import { ChatMessage, UserProfile } from './types';
import { generateId } from './utils';

// Integrated your Supabase credentials
const supabaseUrl = 'https://ouhiisuzkcgtiwhpnbvz.supabase.co';
const supabaseKey = 'sb_publishable_HnvBQa9opn-v5YAJR8c1-Q_zwbKFEXv';
const supabase = createClient(supabaseUrl, supabaseKey);

const SQL_SETUP = `
-- 1. Create the messages table
create table messages (
  id bigint primary key generated always as identity,
  created_at timestamp with time zone default now(),
  handle text not null,
  rank text not null,
  content text not null,
  room_id text not null default 'void-room'
);

-- 2. Enable Realtime for this table
alter publication supabase_realtime add table messages;
`.trim();

function App() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [isBooting, setIsBooting] = useState(true);
  const [isJoining, setIsJoining] = useState(false);
  const [loginFields, setLoginFields] = useState({ name: '', title: 'WANDERER' });
  const [networkStatus, setNetworkStatus] = useState<'OFFLINE' | 'CONNECTED'>('OFFLINE');
  const [hasSchemaError, setHasSchemaError] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  // Boot sequence animation
  useEffect(() => {
    const timer = setTimeout(() => setIsBooting(false), 2000);
    return () => clearTimeout(timer);
  }, []);

  // Auto scroll to latest message
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const mapDbToMessage = (payload: any): ChatMessage => ({
    id: payload.id,
    sender: { name: payload.handle, title: payload.rank },
    text: payload.content,
    timestamp: new Date(payload.created_at).getTime(),
    isSystem: payload.handle === 'SYSTEM'
  });

  // Detect missing table/schema errors
  const isTableError = (error: any) => {
    if (!error) return false;
    const msg = error.message?.toLowerCase() || '';
    const code = error.code || '';
    return (
      msg.includes('messages') || 
      msg.includes('schema cache') || 
      msg.includes('relation "public.messages" does not exist') ||
      code === 'PGRST116' || 
      code === '42P01'
    );
  };

  // Initialize Realtime Postgres Change Listener
  useEffect(() => {
    if (!user || hasSchemaError) return;

    const channel = supabase
      .channel('realtime-messages')
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'messages',
          filter: 'room_id=eq.void-room'
        },
        (payload) => {
          const newMessage = mapDbToMessage(payload.new);
          setMessages(prev => {
            if (prev.find(m => m.id === newMessage.id)) return prev;
            return [...prev, newMessage];
          });
        }
      )
      .subscribe((status) => {
        if (status === 'SUBSCRIBED') {
          setNetworkStatus('CONNECTED');
        } else if (status === 'CLOSED' || status === 'CHANNEL_ERROR') {
          setNetworkStatus('OFFLINE');
        }
      });

    return () => {
      supabase.removeChannel(channel);
    };
  }, [user, hasSchemaError]);

  const handleJoin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!loginFields.name.trim()) return;
    setIsJoining(true);

    // Fetch historical data from Supabase
    const { data, error } = await supabase
      .from('messages')
      .select('*')
      .eq('room_id', 'void-room')
      .order('created_at', { ascending: true })
      .limit(50);

    if (error) {
      console.error("Archive retrieval failed", error);
      if (isTableError(error)) {
        setHasSchemaError(true);
        setIsJoining(false);
        return;
      }
    }

    const newUser = { name: loginFields.name.toUpperCase(), title: loginFields.title.toUpperCase() };
    setUser(newUser);
    if (data) {
      setMessages(data.map(mapDbToMessage));
    }
    setIsJoining(false);

    const welcomeMsg: ChatMessage = {
      id: generateId(),
      sender: { name: 'SYSTEM', title: 'KERNEL' },
      text: `UPLINK ESTABLISHED. HUMAN_NODE_ACTIVE. WELCOME, ${newUser.name}.`,
      timestamp: Date.now(),
      isSystem: true
    };
    setMessages(prev => [...prev, welcomeMsg]);
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || !user) return;

    const textContent = inputValue;
    setInputValue('');

    const { error } = await supabase.from('messages').insert({
      handle: user.name,
      rank: user.title,
      content: textContent,
      room_id: 'void-room'
    });

    if (error) {
      console.error("Packet loss", error);
      if (isTableError(error)) {
        setHasSchemaError(true);
      }
      setMessages(prev => [...prev, {
        id: generateId(),
        sender: { name: 'SYSTEM', title: 'ERROR' },
        text: `SIGNAL DROPPED: ${error.message || 'Unknown Error'}`,
        timestamp: Date.now(),
        isSystem: true
      }]);
    }
  };

  if (isBooting) {
    return (
      <div className="terminal-container boot-screen">
        <div className="scanlines"></div>
        <div className="boot-text">
          <p>LOAD "VOID_OS_V2.2",8,1</p>
          <p>CHECKING SUPABASE_UPLINK...</p>
          <p>PINGING DB_NODES...</p>
          <p>READY.</p>
          <span className="cursor">_</span>
        </div>
      </div>
    );
  }

  if (hasSchemaError) {
    return (
      <div className="terminal-container login-screen schema-error">
        <div className="scanlines"></div>
        <div className="crt-glow"></div>
        <div className="login-form alert">
          <h2 style={{ color: '#ff3333' }}>SYSTEM_FAILURE: SCHEMA_MISSING</h2>
          <p style={{ fontSize: '0.8rem', color: '#ff8888', marginBottom: '20px' }}>
            The table 'public.messages' was not found in your Supabase project. 
            Run the following SQL in your Supabase SQL Editor to initialize the void:
          </p>
          <pre className="sql-box">{SQL_SETUP}</pre>
          <p style={{ fontSize: '0.8rem', marginTop: '20px' }}>
            After running the script, refresh this page to re-establish the uplink.
          </p>
          <button onClick={() => window.location.reload()} style={{ marginTop: '20px', background: '#ff3333' }}>
            RE-INITIALIZE UPLINK
          </button>
        </div>
      </div>
    );
  }

  if (!user) {
    return (
      <div className="terminal-container login-screen">
        <div className="scanlines"></div>
        <div className="crt-glow"></div>
        <form className="login-form" onSubmit={handleJoin}>
          <div className="ascii-art">
            <pre>{`
  _   _ _____ ___  _   _ 
 | \\ | | ____/ _ \\| \\ | |
 |  \\| |  _|| | | |  \\| |
 | |\\  | |__| |_| | |\\  |
 |_| \\_|_____\\___/|_| \\_|
     HUMAN_ACCESS_ONLY
            `}</pre>
          </div>
          <div className="input-group">
            <label>ENTER IDENTITY:</label>
            <input 
              autoFocus
              maxLength={15}
              placeholder="HANDLE..."
              value={loginFields.name}
              onChange={e => setLoginFields({...loginFields, name: e.target.value})}
              disabled={isJoining}
            />
          </div>
          <div className="input-group">
            <label>ASSIGN RANK:</label>
            <input 
              maxLength={20}
              placeholder="e.g. DATA_RUNNER"
              value={loginFields.title}
              onChange={e => setLoginFields({...loginFields, title: e.target.value})}
              disabled={isJoining}
            />
          </div>
          <button type="submit" disabled={isJoining || !loginFields.name}>
            {isJoining ? 'SYNCHRONIZING HUMAN ARCHIVES...' : 'CONNECT TO THE REAL VOID'}
          </button>
        </form>
      </div>
    );
  }

  return (
    <div className="terminal-container main-chat">
      <div className="scanlines"></div>
      <div className="crt-glow"></div>

      <header className="terminal-header">
        <div className="status-bit">USER: {user.name}</div>
        <div className="status-bit">RANK: {user.title}</div>
        <div className={`status-bit ${networkStatus.toLowerCase()}`}>
          VOID_SYNC: {networkStatus}
        </div>
      </header>

      <div className="message-area" ref={scrollRef}>
        {messages.map((msg) => (
          <div key={msg.id} className={`message-item ${msg.isSystem ? 'system' : ''} ${msg.sender.name === user.name ? 'self' : ''}`}>
            <div className="msg-meta">
              <span className="msg-name">[{msg.sender.name}]</span>
              <span className="msg-title">({msg.sender.title})</span>
            </div>
            <div className="msg-text">{msg.text}</div>
          </div>
        ))}
      </div>

      <form className="terminal-input-bar" onSubmit={handleSendMessage}>
        <span className="prompt">></span>
        <input 
          ref={inputRef}
          autoFocus
          value={inputValue}
          onChange={e => setInputValue(e.target.value)}
          placeholder="ENTER MESSAGE..."
          autoComplete="off"
        />
      </form>

      <footer className="terminal-footer">
        SUPABASE_HUMAN_CDC | ARCHIVE: {messages.length} NODES | AI_GHOSTS_PURGED: TRUE
      </footer>
    </div>
  );
}

const rootElement = document.getElementById('root');
if (rootElement) {
  const root = ReactDOM.createRoot(rootElement);
  root.render(<App />);
}

